"""Swiss public transport connections via transport.opendata.ch, with a scripted timetable fallback."""

from __future__ import annotations

import logging
from datetime import datetime, timedelta

import httpx

from .config import settings

log = logging.getLogger(__name__)

API = "https://transport.opendata.ch/v1/connections"
LONG_DISTANCE = ("IC", "EC", "ICE", "IR", "RE")

# Typical Winterthur -> Zürich HB pattern per hour: (product, minute, duration_min, platform).
_SCRIPTED_PATTERN = [("IR 75", 1, 25, "4"), ("S11", 9, 19, "3"), ("IR 13", 24, 28, "3"), ("IC 8", 31, 26, "4"), ("S12", 52, 20, "7")]


def _parse_ts(value: str) -> datetime:
    return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S%z").astimezone(settings.tz)


def _simplify(conn: dict) -> dict:
    dep = _parse_ts(conn["from"]["departure"])
    arr = _parse_ts(conn["to"]["arrival"])
    return {
        "departure": dep.isoformat(),
        "arrival": arr.isoformat(),
        "duration_min": int((arr - dep).total_seconds() // 60),
        "transfers": conn.get("transfers", 0),
        "products": [p.replace("  ", " ") for p in conn.get("products") or []],
        "platform": conn["from"].get("platform"),
        "from_station": conn["from"]["station"]["name"],
        "to_station": conn["to"]["station"]["name"],
    }


def _mark_recommended(items: list[dict], when: datetime, is_arrival_time: bool) -> list[dict]:
    if not items:
        return items
    if is_arrival_time:
        on_time = [c for c in items if datetime.fromisoformat(c["arrival"]) <= when] or items
        fast = [c for c in on_time if any(p.startswith(LONG_DISTANCE) for p in c["products"])]
        best = max(fast or on_time, key=lambda c: c["departure"])
    else:
        best = items[0]
    for c in items:
        c["recommended"] = c is best
    return items


def scripted_connections(origin: str, destination: str, when: datetime, is_arrival_time: bool, limit: int) -> list[dict]:
    """Plausible Winterthur -> Zürich timetable used when the live API is unreachable."""
    base = when.replace(minute=0, second=0, microsecond=0)
    items = []
    for hour_offset in (-2, -1, 0, 1):
        for product, minute, dur, platform in _SCRIPTED_PATTERN:
            dep = base + timedelta(hours=hour_offset, minutes=minute)
            items.append(
                {
                    "departure": dep.isoformat(),
                    "arrival": (dep + timedelta(minutes=dur)).isoformat(),
                    "duration_min": dur,
                    "transfers": 0,
                    "products": [product],
                    "platform": platform,
                    "from_station": origin,
                    "to_station": destination,
                }
            )
    items.sort(key=lambda c: c["departure"])
    if is_arrival_time:
        items = [c for c in items if datetime.fromisoformat(c["arrival"]) <= when][-limit:]
    else:
        items = [c for c in items if datetime.fromisoformat(c["departure"]) >= when][:limit]
    return _mark_recommended(items, when, is_arrival_time)


def connections(origin: str, destination: str, when: datetime, is_arrival_time: bool = True, limit: int = 4) -> dict:
    """Connections around `when`; `source` is "live" or "scripted" (fallback)."""
    limit = max(1, min(limit, 6))
    when = when.astimezone(settings.tz)
    params = {
        "from": origin,
        "to": destination,
        "date": when.strftime("%Y-%m-%d"),
        "time": when.strftime("%H:%M"),
        "isArrivalTime": 1 if is_arrival_time else 0,
        "limit": limit if not is_arrival_time else limit + 2,
    }
    try:
        resp = httpx.get(API, params=params, timeout=settings.sbb_timeout_s)
        resp.raise_for_status()
        raw = resp.json().get("connections") or []
        items = [_simplify(c) for c in raw]
        if is_arrival_time:
            items = [c for c in items if datetime.fromisoformat(c["arrival"]) <= when][-limit:] or items[:limit]
        else:
            items = items[:limit]
        if not items:
            raise ValueError("no connections returned")
        return {
            "from": items[0]["from_station"],
            "to": items[0]["to_station"],
            "source": "live",
            "items": _mark_recommended(items, when, is_arrival_time),
        }
    except Exception as exc:
        log.warning("SBB lookup failed (%s -> %s), using scripted timetable: %s", origin, destination, exc)
        return {
            "from": origin,
            "to": destination,
            "source": "scripted",
            "items": scripted_connections(origin, destination, when, is_arrival_time, limit),
        }


def route_url(origin: str, destination: str) -> str:
    return str(
        httpx.URL(
            "https://www.google.com/maps/dir/",
            params={"api": 1, "origin": origin, "destination": destination, "travelmode": "transit"},
        )
    )

"""UI-spec card assembly shared by the Gemini agent and the scripted fallback."""

from __future__ import annotations

from datetime import datetime
from typing import Any

from .config import settings
from .models import Action, Card
from .sbb import route_url
from .state import PendingAction, new_id, store

SECTION_TYPES = {"event", "conflict", "free", "connections", "slots", "message", "reminder", "fields", "text"}

_DAYS = {"en": ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"], "de": ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"]}
_MONTHS = {
    "en": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
    "de": ["Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez"],
}

_TEXT = {
    "open_route": {"en": "Open route", "de": "Route öffnen"},
    "dismiss": {"en": "Dismiss", "de": "Schliessen"},
}


def t(key: str, locale: str) -> str:
    return _TEXT[key].get(locale, _TEXT[key]["en"])


def parse_dt(value: str | datetime) -> datetime:
    dt = value if isinstance(value, datetime) else datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=settings.tz)
    return dt.astimezone(settings.tz)


def hm(value: str | datetime) -> str:
    return parse_dt(value).strftime("%H:%M")


def day_label(value: str | datetime, locale: str = "en") -> str:
    d = parse_dt(value)
    loc = locale if locale in _DAYS else "en"
    if loc == "de":
        return f"{_DAYS[loc][d.weekday()]} {d.day}. {_MONTHS[loc][d.month - 1]}"
    return f"{_DAYS[loc][d.weekday()]} {d.day} {_MONTHS[loc][d.month - 1]}"


def confirm_action(act: PendingAction, primary: bool) -> Action:
    return Action(
        id=act.id,
        label=act.label,
        kind="confirm",
        style="primary" if primary else "secondary",
        requires_confirmation=True,
        tool=act.tool,
        preview=act.preview,
        expires_at=act.expires_at.isoformat(),
    )


def build_card(
    *,
    card_type: str,
    status: str,
    title: str,
    summary: str,
    sections: list[dict[str, Any]],
    proposals: list[PendingAction],
    locale: str,
    source: str,
    subtitle: str | None = None,
    speak: str | None = None,
    route: tuple[str, str] | None = None,
    followups: list[str] | None = None,
) -> Card:
    actions = [confirm_action(a, i == 0) for i, a in enumerate(proposals)]
    if route:
        actions.append(Action(id=new_id("act"), label=t("open_route", locale), kind="open_url", url=route_url(*route)))
    for text in (followups or [])[:2]:
        actions.append(Action(id=new_id("act"), label=text, kind="followup", intent=text))
    actions.append(Action(id=new_id("act"), label=t("dismiss", locale), kind="dismiss", style="ghost"))
    return Card(
        card_id=new_id("card"),
        card_type=card_type if card_type in Card.model_fields["card_type"].annotation.__args__ else "info",
        status=status if status in {"ok", "conflict", "warning", "error"} else "ok",
        title=title,
        subtitle=subtitle,
        summary=summary,
        speak=speak or summary,
        large_mode=store.profile.large_mode,
        source=source,
        sections=[s for s in sections if s.get("type") in SECTION_TYPES],
        actions=actions,
    )


def error_card(message: str, locale: str = "en") -> Card:
    title = "Das hat nicht geklappt" if locale == "de" else "That did not work"
    return build_card(
        card_type="error", status="error", title=title, summary=message, sections=[], proposals=[], locale=locale, source="fallback"
    )


def result_card(card_type: str, title: str, summary: str, sections: list[dict[str, Any]] | None = None) -> Card:
    return Card(
        card_id=new_id("card"),
        card_type=card_type,
        status="ok",
        title=title,
        summary=summary,
        speak=summary,
        large_mode=store.profile.large_mode,
        source="agent",
        sections=sections or [],
        actions=[],
    )

"""Agent tools.

Read tools run immediately.
Write tools never run during /intent: they register a PendingAction with a server-written preview and only execute via /confirm.
"""

from __future__ import annotations

import logging
from dataclasses import dataclass, field
from datetime import datetime, time, timedelta
from typing import Any
from urllib.parse import quote

from . import sbb
from .calendar_source import ME, busy_and_conflicts, free_slots, get_calendar
from .cards import day_label, hm, parse_dt
from .models import Profile
from .state import PendingAction, store

log = logging.getLogger(__name__)

WRITE_TOOLS = {"calendar_create", "calendar_move", "set_reminder", "draft_message"}

_ISO = "ISO 8601 date-time with offset, e.g. 2026-10-10T18:00:00+02:00"

TOOL_DECLARATIONS: list[dict[str, Any]] = [
    {
        "type": "function",
        "name": "calendar_free_busy",
        "description": "Read the user's calendar between start and end. Returns busy events (id, title, start, end) that overlap the window.",
        "parameters": {
            "type": "object",
            "properties": {"start": {"type": "string", "description": _ISO}, "end": {"type": "string", "description": _ISO}},
            "required": ["start", "end"],
        },
    },
    {
        "type": "function",
        "name": "sbb_connections",
        "description": "Swiss public transport connections (SBB timetable). Use station or town names. With is_arrival_time=true, `datetime` is the latest arrival.",
        "parameters": {
            "type": "object",
            "properties": {
                "origin": {"type": "string", "description": "Departure station or town, e.g. Winterthur"},
                "destination": {"type": "string", "description": "Arrival station or town, e.g. Zürich HB"},
                "datetime": {"type": "string", "description": _ISO},
                "is_arrival_time": {"type": "boolean"},
                "limit": {"type": "integer", "description": "1-6, default 4"},
            },
            "required": ["origin", "destination", "datetime"],
        },
    },
    {
        "type": "function",
        "name": "shared_free_slot",
        "description": "Find free slots shared by the user and contacts (by contact id from the profile) on one day.",
        "parameters": {
            "type": "object",
            "properties": {
                "participants": {"type": "array", "items": {"type": "string"}, "description": "Contact ids; the user is always included"},
                "date": {"type": "string", "description": "YYYY-MM-DD"},
                "duration_min": {"type": "integer"},
                "earliest": {"type": "string", "description": "HH:MM, default 08:00"},
                "latest": {"type": "string", "description": "HH:MM, default 22:00"},
            },
            "required": ["participants", "date", "duration_min"],
        },
    },
    {
        "type": "function",
        "name": "calendar_create",
        "description": "PROPOSE creating a calendar event. Does not write; returns an action_id the human must approve.",
        "parameters": {
            "type": "object",
            "properties": {
                "title": {"type": "string"},
                "start": {"type": "string", "description": _ISO},
                "end": {"type": "string", "description": _ISO},
                "location": {"type": "string"},
                "description": {"type": "string"},
            },
            "required": ["title", "start", "end"],
        },
    },
    {
        "type": "function",
        "name": "calendar_move",
        "description": "PROPOSE moving an existing calendar event (id from calendar_free_busy) to a new time. Does not write; returns an action_id the human must approve.",
        "parameters": {
            "type": "object",
            "properties": {
                "event_id": {"type": "string"},
                "new_start": {"type": "string", "description": _ISO},
                "new_end": {"type": "string", "description": _ISO + "; default keeps the duration"},
            },
            "required": ["event_id", "new_start"],
        },
    },
    {
        "type": "function",
        "name": "set_reminder",
        "description": "PROPOSE a reminder at a time. Does not write; returns an action_id the human must approve.",
        "parameters": {
            "type": "object",
            "properties": {"text": {"type": "string"}, "at": {"type": "string", "description": _ISO}},
            "required": ["text", "at"],
        },
    },
    {
        "type": "function",
        "name": "draft_message",
        "description": "PROPOSE a message to a contact from the profile (e.g. notify family). Only a draft; nothing is sent until the human approves.",
