"""Scripted planner used when Gemini (or the network) is unavailable.

It reads the event from the page text with plain parsing, uses the same tools as the agent
(calendar, SBB with its own scripted timetable fallback) and builds the same kind of turn.
"""

from __future__ import annotations

import re
from datetime import date, datetime, time, timedelta
from typing import Any

from .calendar_source import ME, busy_and_conflicts
from .compose import build_turn
from .fmt import hm
from .models import IntentRequest
from .tools import RequestCtx, propose_calendar_bundle, propose_draft_message, propose_set_reminder, sbb_connections

_MONTHS = {
    "jan": 1, "januar": 1, "january": 1, "feb": 2, "februar": 2, "february": 2, "mar": 3, "mär": 3, "märz": 3, "march": 3,
    "apr": 4, "april": 4, "may": 5, "mai": 5, "jun": 6, "juni": 6, "june": 6, "jul": 7, "juli": 7, "july": 7,
    "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9, "oct": 10, "okt": 10, "oktober": 10, "october": 10,
    "nov": 11, "november": 11, "dec": 12, "dez": 12, "dezember": 12, "december": 12,
}
_MONTH_RE = "|".join(sorted(_MONTHS, key=len, reverse=True))
_TIME = r"(\d{1,2})(?::(\d{2}))?\s*(am|pm|AM|PM|a\.m\.|p\.m\.)?"
_CITIES = ["Zürich", "Zurich", "Winterthur", "Bern", "Basel", "Lausanne", "Genève", "Geneva", "Luzern", "Lucerne", "St. Gallen", "Lugano", "Zug"]
_DEFAULT_START, _DEFAULT_END = time(18, 0), time(21, 0)


def _text_sources(req: IntentRequest) -> str:
    c = req.context
    parts = [
        c.selection.text if c.selection else None,
        c.selection.element.text if c.selection and c.selection.element else None,
        c.gaze.text if c.gaze else None,
        c.title,
        (c.page_text or "")[:5000],
    ]
    return "\n".join(p for p in parts if p)


def _parse_date(text: str, today: date) -> date:
    low = text.lower()
    if m := re.search(r"\b(20\d\d)-(\d{2})-(\d{2})\b", text):
        return date(int(m[1]), int(m[2]), int(m[3]))
    if m := re.search(r"\b(\d{1,2})\.(\d{1,2})\.(20\d\d)\b", text):
        return date(int(m[3]), int(m[2]), int(m[1]))
    if m := re.search(rf"\b({_MONTH_RE})\.?\s+(\d{{1,2}})(?:st|nd|rd|th)?\b", low):
        return _with_year(today, _MONTHS[m[1]], int(m[2]))
    if m := re.search(rf"\b(\d{{1,2}})\.?\s+({_MONTH_RE})\b", low):
        return _with_year(today, _MONTHS[m[2]], int(m[1]))
    if re.search(r"\b(tomorrow|morgen)\b", low):
        return today + timedelta(days=1)
    return today


def _with_year(today: date, month: int, day: int) -> date:
    try:
        d = date(today.year, month, day)
    except ValueError:
        return today
    return d if d >= today - timedelta(days=1) else date(today.year + 1, month, day)


def _to_time(h: str, m: str | None, ampm: str | None) -> time | None:
    hour, minute = int(h), int(m or 0)
    if ampm:
        ap = ampm.lower().replace(".", "")
        if ap == "pm" and hour < 12:
            hour += 12
        if ap == "am" and hour == 12:
            hour = 0
    if not (0 <= hour < 24 and 0 <= minute < 60):
        return None
    return time(hour, minute)


def _parse_times(text: str) -> tuple[time, time]:
    rng = re.search(rf"{_TIME}\s*(?:-|–|—|to|bis)\s*{_TIME}", text)
    if rng and (rng[2] or rng[3]) and (rng[5] or rng[6]):
        start = _to_time(rng[1], rng[2], rng[3] or rng[6])
        end = _to_time(rng[4], rng[5], rng[6])
        if start and end:
            return start, end
    single = re.search(r"\b(\d{1,2}):(\d{2})\s*(am|pm|AM|PM)?", text) or re.search(r"\b(\d{1,2})()\s*(am|pm|AM|PM)\b", text)
    if single and (start := _to_time(single[1], single[2] or None, single[3])):
        return start, (datetime.combine(date.today(), start) + timedelta(hours=3)).time()
    return _DEFAULT_START, _DEFAULT_END


def _parse_location(text: str) -> str | None:
    for city in _CITIES:
        if re.search(rf"\b{re.escape(city)}\b", text, re.IGNORECASE):
            return "Zürich" if city.lower() in {"zurich", "zürich"} else city
    return None


def _clean_title(title: str) -> str:
    title = re.split(r"\s+[|·–-]\s+Luma\b", title)[0]
    return title.strip() or "Event"


def parse_event(req: IntentRequest, now: datetime) -> dict[str, Any]:
    text = _text_sources(req)
    day = _parse_date(text, now.date())
    t0, t1 = _parse_times(text)
    start = datetime.combine(day, t0, now.tzinfo)
    end = datetime.combine(day, t1, now.tzinfo)
    if end <= start:
        end += timedelta(days=1)
    loc = _parse_location(text)
    ev = {"title": _clean_title(req.context.title), "start": start.isoformat(), "end": end.isoformat()}
    if loc:
        ev["location"] = loc
    return ev


def _origin(intent: str, home: str) -> str:
    m = re.search(r"\b(?:from|von|ab)\s+([A-ZÄÖÜ][\w.\-äöüÄÖÜ]*(?:\s+(?:HB|[A-ZÄÖÜ][\w.\-äöüÄÖÜ]*))*)", intent)
    return m[1] if m else home


def _station(location: str | None) -> str:
    if not location or location.lower() in {"zürich", "zurich"}:
        return "Zürich HB"
    return location


def _has(pattern: str, text: str) -> bool:
    return re.search(pattern, text, re.IGNORECASE) is not None


def plan(req: IntentRequest, ctx: RequestCtx) -> dict[str, Any]:
    intent = req.intent
    de = ctx.locale == "de"
    wants_travel = _has(r"get there|how do i get|train|travel|commute|route|hinkommen|anreise|zug|fahr|\bfrom\b|\bvon\b", intent)
    wants_free = _has(r"\bfree\b|available|busy|conflict|calendar|frei|zeit|kalender|termin", intent)
    wants_reminder = _has(r"remind|erinner", intent)
    contact = next(
        (c for c in ctx.profile.contacts if _has(rf"\b({re.escape(c.name)}|{re.escape(c.id)}|{re.escape(c.relation or c.id)})\b", intent)),
        None,
    )
    if contact is None and _has(r"\b(mum|mama|mother|mutter)\b", intent):
        contact = next((c for c in ctx.profile.contacts if c.relation == "mother"), None)
    wants_message = contact is not None and _has(r"tell|notify|message|text|let .* know|sag|schreib|benachrichtig|inform", intent)

    ev = parse_event(req, ctx.now)
    ctx.event = ev
    start, end = datetime.fromisoformat(ev["start"]), datetime.fromisoformat(ev["end"])
    conflicts = busy_and_conflicts(start, end, ME)
    ctx.busy_checked.append((start, end))

    train = None
    if wants_travel or not (wants_free or wants_reminder or wants_message):
        origin = _origin(intent, ctx.profile.home)
        target = start - timedelta(minutes=10)
        if target > ctx.now:
            res = sbb_connections(ctx, origin, _station(ev.get("location")), target.isoformat(), True, 4)
        else:
            res = sbb_connections(ctx, origin, _station(ev.get("location")), ctx.now.isoformat(), False, 4)
        items = res.get("items") or []
        train = next((c for c in items if c.get("recommended")), items[0] if items else None)

    entries = [{"title": ev["title"], "start": ev["start"], "end": ev["end"], "location": ev.get("location")}]
    if train:
        product = (train.get("products") or ["Train"])[0]
        entries.append({"title": f"{product} {ctx.connections['from']} → {ctx.connections['to']}", "start": train["departure"], "end": train["arrival"]})
    label = ("Event + Zug eintragen" if de else "Add event + train") if train else ("Eintragen" if de else "Add to calendar")
    propose_calendar_bundle(ctx, entries, label)

    if wants_reminder:
        at = datetime.fromisoformat(train["departure"]) - timedelta(minutes=15) if train else start - timedelta(hours=1)
        at = max(at, ctx.now + timedelta(minutes=5))
        text = (f"Los zu {ev['title']}" if de else f"Leave for {ev['title']}") if train else ev["title"]
        propose_set_reminder(ctx, text, at.isoformat())
    if wants_message and contact:
        body = (
            f"Hi {contact.name}, ich bin heute Abend bei {ev['title']} ({hm(start)}-{hm(end)}). Ich melde mich, wenn ich losfahre."
            if de
            else f"Hi {contact.name}, I'm at {ev['title']} tonight ({hm(start)}-{hm(end)}). I'll text you when I head home."
        )
        propose_draft_message(ctx, contact.id, body)

    say = _say(ctx, conflicts, train)
    return build_turn(ctx, say, [{"component": "EventCard", "event": ev}], "fallback")


def _say(ctx: RequestCtx, conflicts: list, train: dict[str, Any] | None) -> str:
    de = ctx.locale == "de"
    parts = []
    if conflicts:
        c = conflicts[0]
        parts.append(f"Achtung: {c.title} um {hm(c.start)} überschneidet sich." if de else f"Heads up: {c.title} overlaps at {hm(c.start)}.")
    else:
        parts.append("Du hast dann Zeit." if de else "You're free then.")
    if train:
        product = (train.get("products") or ["train"])[0]
        conn = ctx.connections or {}
        parts.append(
            f"Der {product} um {hm(train['departure'])} ab {conn.get('from')} ist um {hm(train['arrival'])} in {conn.get('to')}."
            if de
            else f"The {hm(train['departure'])} {product} from {conn.get('from')} gets you to {conn.get('to')} by {hm(train['arrival'])}."
        )
    return " ".join(parts)

"""HTTP API (contract: docs/API.md)."""

from __future__ import annotations

import asyncio
import json
import logging
import re
from concurrent.futures import ThreadPoolExecutor
from concurrent.futures import TimeoutError as FutureTimeout
from datetime import datetime
from typing import Any

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse, StreamingResponse

from . import __version__, a2ui, fallback
from .agent import run_agent
from .calendar_source import get_calendar, mock_calendar
from .compose import plain_turn
from .config import settings
from .fmt import parse_dt
from .models import A2UIActionMessage, ConfirmRequest, IntentRequest, Profile, ProfileUpdate, VoiceTokenRequest
from .state import store
from .tools import RequestCtx, execute_op

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s: %(message)s")
log = logging.getLogger("micro_intent")

app = FastAPI(title="Micro Intent API", version=__version__)
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])

_pool = ThreadPoolExecutor(max_workers=8)


def _ctx(req: IntentRequest) -> RequestCtx:
    now = datetime.now(settings.tz)
    if req.now:
        try:
            now = parse_dt(req.now)
        except ValueError:
            pass
    return RequestCtx(profile=store.profile, now=now, locale=req.locale or store.profile.locale, url=req.context.url)


def plan_turn(req: IntentRequest) -> dict[str, Any]:
    """Gemini agent with a hard deadline; the scripted planner takes over on any failure."""
    if settings.gemini_api_key and not settings.force_fallback:
        future = _pool.submit(run_agent, req, _ctx(req))
        try:
            return future.result(timeout=settings.agent_timeout_s)
        except FutureTimeout:
            log.warning("agent timed out after %ss, using fallback", settings.agent_timeout_s)
        except Exception as exc:
            log.warning("agent failed, using fallback: %s: %s", type(exc).__name__, exc)
    try:
        return fallback.plan(req, _ctx(req))
    except Exception as exc:
        log.exception("fallback failed")
        locale = req.locale or store.profile.locale
        say = "Das hat gerade nicht geklappt. Versuch es nochmal." if locale == "de" else "Sorry, that did not work. Please try again."
        return plain_turn(say, "fallback") | {"error": f"{type(exc).__name__}: {exc}"}


@app.post("/intent")
def intent(req: IntentRequest) -> dict[str, Any]:
    return plan_turn(req)


def _filler(req: IntentRequest) -> str:
    de = (req.locale or store.profile.locale) == "de"
    travel = re.search(r"get there|train|travel|from|zug|hinkommen|von", req.intent, re.IGNORECASE)
    cal = re.search(r"free|busy|calendar|frei|zeit|kalender", req.intent, re.IGNORECASE)
    if travel and cal:
        return "Ich prüfe deinen Kalender und die Züge." if de else "Checking your calendar and trains."
    if travel:
        return "Ich schaue nach Verbindungen." if de else "Looking up connections."
    if cal:
        return "Ich schaue in deinen Kalender." if de else "Checking your calendar."
    return "Einen Moment." if de else "One moment."


def _sse(event: str, data: dict[str, Any]) -> str:
    return f"event: {event}\ndata: {json.dumps(data, ensure_ascii=False)}\n\n"


@app.post("/intent/stream")
async def intent_stream(req: IntentRequest) -> StreamingResponse:
    async def events():
        yield _sse("orb", {"state": "thinking"})
        yield _sse("filler", {"say": _filler(req)})
        yield _sse("orb", {"state": "searching"})
        turn = await asyncio.to_thread(plan_turn, req)
        yield _sse("turn", turn)

    return StreamingResponse(events(), media_type="text/event-stream", headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


# ---------- human checkpoint ----------

_REJECT_SAY = {
    "reject": {"en": "Okay, I won't do that.", "de": "Okay, mache ich nicht."},
    "skip": {"en": "Okay, skipping the event.", "de": "Okay, du lässt den Termin aus."},
    "keep": {"en": "Okay, keeping both as they are.", "de": "Okay, beides bleibt wie es ist."},
}


def handle_action(name: str, action_id: str, edits: dict[str, Any], surface_id: str | None) -> JSONResponse:
    locale = store.profile.locale
    if name not in {"confirm", *_REJECT_SAY}:
        raise HTTPException(422, f"unknown action name {name}")
    act = store.get_action(action_id) if action_id else None
    if act is None and not (action_id == "" and name in {"skip", "keep"}):
        return JSONResponse(
            {"action_id": action_id, "status": "not_found", "message": "Unknown or expired action."} | plain_turn("", "agent"),
            status_code=404,
        )
    sid = surface_id or (act.surface_id if act else None)
    cards = [a2ui.delete_surface(sid)] if sid else []
    if act is not None and act.status != "pending":
        return JSONResponse(
            {"action_id": action_id, "status": "already_done", "message": f"Already {act.status}.", "result": act.result} | plain_turn("", "agent")
        )

    if name != "confirm":
        if act is not None:
            act.status = "rejected"
        say = _REJECT_SAY[name].get(locale, _REJECT_SAY[name]["en"])
        return JSONResponse({"action_id": action_id, "status": "rejected", "message": say} | plain_turn(say, "agent", cards))

    try:
        results = [execute_op(op, edits) for op in act.ops]
    except Exception as exc:
        log.warning("action %s failed: %s", action_id, exc)
        msg = f"{type(exc).__name__}: {exc}"
        say = "Das hat nicht geklappt." if locale == "de" else "That did not work."
        return JSONResponse({"action_id": action_id, "status": "failed", "message": msg} | plain_turn(say, "agent"))
    act.status = "done"
    act.result = results[0] if len(results) == 1 else {"results": results}
    message = " ".join(r.get("message", "") for r in results).strip()
    say = ("Erledigt. " if locale == "de" else "Done. ") + message
    return JSONResponse({"action_id": action_id, "status": "done", "message": message, "result": act.result} | plain_turn(say, "agent", cards))


@app.post("/action")
def action(msg: A2UIActionMessage) -> JSONResponse:
    ctx = dict(msg.action.context)
    action_id = str(ctx.pop("action_id", "") or "")
    return handle_action(msg.action.name, action_id, ctx, msg.action.surfaceId)


@app.post("/confirm")
def confirm(req: ConfirmRequest) -> JSONResponse:
    return handle_action("confirm" if req.approved else "reject", req.action_id, req.edits or {}, None)


# ---------- profile, voice, ops ----------


@app.get("/profile")
def get_profile() -> Profile:
    return store.profile


@app.put("/profile")
def put_profile(upd: ProfileUpdate) -> Profile:
    return store.update_profile(upd)


@app.post("/voice/token")
def voice_token(_: VoiceTokenRequest | None = None) -> dict[str, Any]:
    if not settings.gemini_api_key:
        raise HTTPException(503, "voice is not configured (no Gemini key on the backend)")
    from .voice import mint_live_token

    try:
        return {"provider": "gemini-live"} | mint_live_token()
    except Exception as exc:
        log.warning("voice token failed: %s", exc)
        raise HTTPException(502, f"could not mint a Gemini Live token: {type(exc).__name__}") from exc


@app.get("/health")
def health() -> dict[str, Any]:
    return {
        "ok": True,
        "version": __version__,
        "model": settings.model,
        "calendar": get_calendar().name,
        "gemini": bool(settings.gemini_api_key),
        "force_fallback": settings.force_fallback,
    }


@app.post("/demo/reset")
def demo_reset() -> dict[str, bool]:
    mock_calendar.reset()
    store.reset()
    return {"ok": True}

